'use strict';

const { flushDB, seedBucket } = require('../lib/redis-helper');
const { makeConcurrentRequests } = require('../lib/http-client');
const { formatStatusCounts, printStatusTable } = require('../lib/report');

/**
 * Scenario 5: Fairness
 *
 * Two customers on the same effective policy (growth, 300 RPM each).
 * Same initial bucket state (300 tokens each).
 * Both send 500 requests concurrently through Nginx.
 *
 * Expected: Both allowed counts within 2% of each other.
 * Neither starves.
 */
async function scenario05() {
  flushDB();

  const T0 = 1_700_000_000_000;
  seedBucket('acme', 300, T0);
  seedBucket('globex', 300, T0);

  console.log('Configuration:');
  console.log('  Customers: acme, globex (both growth, 300 RPM)');
  console.log('  Initial buckets: both 300 tokens (symmetric)');
  console.log('  Requests: both send 500 concurrently');
  console.log('  Time: frozen at ' + T0);

  const [resA, resB] = await Promise.all([
    makeConcurrentRequests(500, { customerId: 'acme' }, T0),
    makeConcurrentRequests(500, { customerId: 'globex' }, T0),
  ]);

  const allowedA = resA.filter((r) => r.statusCode === 200).length;
  const allowedB = resB.filter((r) => r.statusCode === 200).length;

  console.log('\nResults:');
  console.log('  acme:');
  printStatusTable(formatStatusCounts(allowedA, 500 - allowedA, 0, 0));
  console.log('  globex:');
  printStatusTable(formatStatusCounts(allowedB, 500 - allowedB, 0, 0));

  // Both should get ~300 allowed, within 2% means abs(A-B) <= 0.02 * avg
  const diff = Math.abs(allowedA - allowedB);
  const avg = (allowedA + allowedB) / 2;
  const pctDiff = avg > 0 ? (diff / avg) * 100 : 0;
  const withinTolerance = pctDiff <= 2;

  const pass =
    allowedA >= 280 && allowedA <= 320 &&
    allowedB >= 280 && allowedB <= 320 &&
    withinTolerance;

  return {
    pass,
    details: {
      'acme allowed': allowedA,
      'globex allowed': allowedB,
      'Difference': diff,
      'Percent diff': pctDiff.toFixed(2) + '%',
      'Within 2%': withinTolerance ? 'YES' : 'NO',
      'Expected': 'Both ~300, within 2% of each other',
    },
  };
}

module.exports = scenario05;

'use strict';

const { flushDB, seedBucket } = require('../lib/redis-helper');
const { makeConcurrentRequests } = require('../lib/http-client');
const { formatStatusCounts, printStatusTable } = require('../lib/report');

/**
 * Scenario 2: Customer Isolation
 *
 * Two customers on growth tier (300 RPM each).
 * Seed both buckets to 300.
 * Customer A sends 500 requests concurrently.
 * Customer B sends 100 requests concurrently (at same time).
 *
 * Expected: Customer B gets all 100 (its full budget),
 *           Customer A gets ~300 allowed ~200 denied.
 *           B's bucket untouched by A's activity.
 */
async function scenario02() {
  flushDB();

  const T0 = 1_700_000_000_000;
  seedBucket('acme', 300, T0);
  seedBucket('globex', 300, T0);

  console.log('Configuration:');
  console.log('  Customers: acme, globex (both on growth, 300 RPM each)');
  console.log('  Initial buckets: both 300 tokens');
  console.log('  Time: frozen at ' + T0);
  console.log('  Concurrent: acme sends 500, globex sends 100 (simultaneously)');

  const resultsA = makeConcurrentRequests(500, { customerId: 'acme' }, T0);
  const resultsB = makeConcurrentRequests(100, { customerId: 'globex' }, T0);

  const [resA, resB] = await Promise.all([resultsA, resultsB]);

  const allowedA = resA.filter((r) => r.statusCode === 200).length;
  const deniedA = resA.filter((r) => r.statusCode === 429).length;
  const allowedB = resB.filter((r) => r.statusCode === 200).length;
  const deniedB = resB.filter((r) => r.statusCode === 429).length;

  console.log('\nResults:');
  console.log('  acme:');
  printStatusTable({ '200 OK': allowedA, '429': deniedA });
  console.log('  globex:');
  printStatusTable({ '200 OK': allowedB, '429': deniedB });

  // globex should get all 100 allowed, 0 denied
  // acme should get ~300 allowed, ~200 denied
  const pass =
    allowedB === 100 &&
    deniedB === 0 &&
    allowedA >= 280 && allowedA <= 320 && // ~300 with some variance
    deniedA >= 180 && deniedA <= 220;

  return {
    pass,
    details: {
      'acme allowed': allowedA,
      'acme denied': deniedA,
      'globex allowed': allowedB,
      'globex denied': deniedB,
      'globex isolation': allowedB === 100 ? 'VERIFIED' : 'FAILED',
      'Expected': 'globex: 100 allowed / acme: ~300 allowed, ~200 denied',
    },
  };
}

module.exports = scenario02;

'use strict';

const http = require('http');

const agent = new http.Agent({
  keepAlive: true,
  keepAliveMsecs: 1000,
  maxSockets: 256,
  maxFreeSockets: 256,
});

/**
 * Simple HTTP client for making requests to the rate-limited service.
 * Returns a promise that resolves to { statusCode, headers, body }.
 */
function makeRequest(options, testTimeMs = null) {
  return new Promise((resolve) => {
    const requestOptions = {
      hostname: 'localhost',
      port: 8080,
      path: '/api/v1/ping',
      method: 'GET',
      headers: {
        'X-Customer-Id': options.customerId,
      },
      agent,
      timeout: 5000,
    };

    if (testTimeMs !== null && process.env.RATE_LIMIT_TEST_MODE === 'true') {
      requestOptions.headers['X-Test-Time-Ms'] = String(testTimeMs);
    }

    const req = http.request(requestOptions, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        try {
          const body = JSON.parse(data);
          resolve({
            statusCode: res.statusCode,
            headers: res.headers,
            body,
          });
        } catch {
          resolve({
            statusCode: res.statusCode,
            headers: res.headers,
            body: data,
          });
        }
      });
    });

    req.on('error', (err) => {
      resolve({
        statusCode: 0,
        error: err.message,
      });
    });

    req.on('timeout', () => {
      req.destroy();
      resolve({
        statusCode: 0,
        error: 'timeout',
      });
    });

    req.end();
  });
}

/**
 * Make N requests concurrently.
 */
async function makeConcurrentRequests(n, options, testTimeMs = null) {
  const promises = Array.from({ length: n }, () =>
    makeRequest(options, testTimeMs).catch((err) => ({
      statusCode: 0,
      error: err.message,
    }))
  );
  return Promise.all(promises);
}

/**
 * Make N requests sequentially.
 */
async function makeSequentialRequests(n, options, testTimeMs = null) {
  const results = [];
  for (let i = 0; i < n; i++) {
    const res = await makeRequest(options, testTimeMs).catch((err) => ({
      statusCode: 0,
      error: err.message,
    }));
    results.push(res);
  }
  return results;
}

module.exports = { makeRequest, makeConcurrentRequests, makeSequentialRequests };

#!/usr/bin/env node

'use strict';

const { printScenarioHeader, printScenarioResult, printAggregateSummary } = require('./lib/report');

// Import all 9 scenarios
const scenario01 = require('./scenarios/01-basic-quota');
const scenario02 = require('./scenarios/02-customer-isolation');
const scenario03 = require('./scenarios/03-distributed-correctness');
const scenario04 = require('./scenarios/04-concurrent-contention');
const scenario05 = require('./scenarios/05-fairness');
const scenario06 = require('./scenarios/06-override-activation');
const scenario07 = require('./scenarios/07-boundary-interval');
const scenario08 = require('./scenarios/08-boundary-clamp');
const scenario09 = require('./scenarios/09-burst-and-refill');

const scenarios = [
  { num: 1, name: 'Basic Quota', fn: scenario01 },
  { num: 2, name: 'Customer Isolation', fn: scenario02 },
  { num: 3, name: 'Distributed Correctness', fn: scenario03 },
  { num: 4, name: 'Concurrent Contention', fn: scenario04 },
  { num: 5, name: 'Fairness', fn: scenario05 },
  { num: 6, name: 'Northwind Override Activation', fn: scenario06 },
  { num: 7, name: 'Boundary – Half-Open Interval', fn: scenario07 },
  { num: 8, name: 'Boundary – Capacity Clamp', fn: scenario08 },
  { num: 9, name: 'Burst & Refill', fn: scenario09 },
];

async function runAllScenarios() {
  console.log('╔════════════════════════════════════════════════════════════════════╗');
  console.log('║                  RATE LIMITER HARNESS - All 9 Scenarios             ║');
  console.log('║                          PRD §15 Verification                        ║');
  console.log('╚════════════════════════════════════════════════════════════════════╝');

  const results = [];
  let passed = 0;
  let failed = 0;

  for (const scenario of scenarios) {
    printScenarioHeader(scenario.num, scenario.name);

    try {
      const result = await scenario.fn();
      printScenarioResult(result.pass, result.details);

      results.push({
        name: scenario.name,
        pass: result.pass,
      });

      if (result.pass) {
        passed++;
      } else {
        failed++;
      }
    } catch (err) {
      console.log(`\n✗ EXCEPTION: ${err.message}`);
      console.log(err.stack);

      results.push({
        name: scenario.name,
        pass: false,
      });

      failed++;
    }
  }

  // Print aggregate summary
  printAggregateSummary(results);

  // Exit code
  const exitCode = failed === 0 ? 0 : 1;
  console.log(`Exit code: ${exitCode}\n`);
  process.exit(exitCode);
}

// Set test mode environment
process.env.RATE_LIMIT_TEST_MODE = 'true';

runAllScenarios().catch((err) => {
  console.error('Fatal error:', err);
  process.exit(2);
});
